import * as T from './vendor/three.module.js';
import {OrbitControls} from './vendor/OrbitControls.js';
import {buildPath,PATH_PRESETS,parseDesign,exportDesign} from './path-builder.js';
import {makePart} from './geometry.js';
import {V,exportModel,parseModel} from './engine.js';
import {makeGroup} from './editor-state.js';
const symbols={hill:'M2 18Q8 18 12 7Q16 -2 22 18',s:'M3 20C-2 2 27 22 21 3',bend:'M3 19H9Q20 19 20 5',plus:'M12 4V20M4 12H20',minus:'M4 12H20',fit:'M8 3H3V8M16 3H21V8M3 16V21H8M21 16V21H16',help:'M9 8C9 3 17 3 17 8Q17 10 13 12V15M13 19V19.2',import:'M12 3V15M7 10L12 15L17 10M4 17V21H20V17',export:'M12 16V3M7 8L12 3L17 8M4 17V21H20V17'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${symbols[name]}"/></svg>`;
export function pathBuilderDialog({model,showDialog,commit,kind='track'}){
 let design={kind,points:PATH_PRESETS.hill.map(p=>[...p]),spacing:65,bank:0},selected=1,result=null,view='3d',drag=null,closed=false,hints=true,frame=0;
 showDialog(`<div class="path-heading"><div><h2>Path builder</h2><span>Classic K’NEX</span></div><div class="path-kinds"><button data-path-kind="track">Track</button><button data-path-kind="flexi">Flexi · 190 mm</button></div></div><div class="path-workspace"><div class="path-stage"><div class="path-views"><button data-path-view="3d">3D</button><button data-path-view="top">Top</button><button data-path-view="front">Front</button><button id="path-fit" aria-label="Frame path" title="Frame path">${icon('fit')}</button><button id="path-hints" aria-label="Toggle path hints" title="Toggle hints" aria-pressed="true">${icon('help')}</button></div><div id="path-canvas"></div><div id="path-help">Drag a pink handle · Shift-drag for height · Drag background to orbit</div><span class="path-badge">Layout preview · supports needed</span></div><aside class="path-controls"><div class="path-presets">${Object.keys(PATH_PRESETS).map(id=>`<button data-path-preset="${id}" title="${{hill:'Hill',s:'S-bend',bend:'Corner'}[id]} preset" aria-label="${{hill:'Hill',s:'S-bend',bend:'Corner'}[id]} preset">${icon(id)}</button>`).join('')}</div><div class="path-node-label"><strong>Handles</strong><span><button id="path-add" aria-label="Add path handle" title="Extend with another handle">${icon('plus')}</button><button id="path-remove" aria-label="Remove selected handle" title="Remove selected handle">${icon('minus')}</button></span></div><div id="path-nodes"></div><div class="path-coordinates">${['x','y','z'].map(a=>`<label>${a.toUpperCase()} <input id="path-${a}" aria-label="Handle ${a.toUpperCase()}" type="number" min="-2500" max="2500" step="5"></label>`).join('')}</div><small id="path-units">Handle position · mm</small><div id="path-track-controls"><label class="path-input">Tie spacing <span><input id="path-spacing" type="number" min="30" max="190" value="65" step="5" aria-label="Cross-tie spacing"> mm</span></label><label class="path-input">Bank <span><input id="path-bank" type="number" min="-60" max="60" value="0" step="5" aria-label="Track bank"> °</span></label></div><div id="path-stats" aria-live="polite"></div><div id="path-error" role="alert"></div><button id="path-apply" class="button">Add to model</button><div class="path-files"><button id="path-import">${icon('import')} Import path</button><button id="path-export">${icon('export')} Save path</button><input id="path-file" type="file" accept=".json,application/json" hidden></div><details class="path-details"><summary>Parts & build limits</summary><p id="path-source"></p><p>Photo-based shapes. Cross-tie gauge, tubing section, bend radius and twist limits are unverified. No elastic flex, coaster-car physics or automatic support frames yet.</p><p id="path-radius"></p><p>JSON import uses <code>knex-path</code> version 1, XYZ points in millimetres. Other coaster formats need conversion.</p></details></aside></div>`);
 const dialog=document.querySelector('#dialog'),$=s=>dialog.querySelector(s);dialog.classList.add('path-dialog');
 const scene=new T.Scene();scene.background=new T.Color('#1b2330');const camera=new T.PerspectiveCamera(38,1,.1,20000),renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=T.SRGBColorSpace;$('#path-canvas').append(renderer.domElement);renderer.domElement.setAttribute('aria-label','3D path preview. Select a handle to edit its coordinates.');
 const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;scene.add(new T.HemisphereLight(0xddefff,0x48516a,2.5));const light=new T.DirectionalLight(0xffffff,3);light.position.set(-100,400,200);scene.add(light);
 const grid=new T.GridHelper(1600,32,0x43536c,0x2d384c);scene.add(grid);const parts=new T.Group(),handles=new T.Group(),guides=new T.Group();scene.add(parts,handles,guides);
 const ray=new T.Raycaster(),pointer=new T.Vector2();let drawn=[];
 function clear(){for(const g of drawn){if(g.userData.dynamic)g.traverse(o=>{o.geometry?.dispose();if(o.material)o.material.dispose();});}drawn=[];parts.clear();for(const g of[handles,guides]){g.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});g.clear();}}
 function nodes(){const root=$('#path-nodes');root.innerHTML=design.points.map((_,i)=>`<button data-path-node="${i}" aria-label="Handle ${i+1}" aria-pressed="${selected===i}">${i+1}</button>`).join('');root.querySelectorAll('button').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.pathNode);redraw(false);});['x','y','z'].forEach((a,i)=>$('#path-'+a).value=+design.points[selected][i].toFixed(1));$('#path-remove').disabled=design.points.length<=2;$('#path-add').disabled=design.points.length>=24;}
 function redraw(refreshNodes=true){if(design.kind==='flexi'){try{const r=buildPath(design),origin=V(design.points[0]);design.points=design.points.map(p=>V(p).sub(origin).multiplyScalar(r.scale).add(origin).toArray());}catch{}}clear();$('#path-error').textContent='';result=null;try{result=buildPath(design);for(const p of result.model.parts){const g=makePart(p.type,p);g.position.fromArray(p.pos);g.quaternion.fromArray(p.quat);g.userData.dynamic=!!p.path;parts.add(g);drawn.push(g);}$('#path-stats').innerHTML=design.kind==='track'?`<strong>${result.tieCount}</strong> cross-ties <span>+ 2 tubing cuts</span><small>${result.railLengths.map(l=>(l/1000).toFixed(2)+' m').join(' / ')}</small>`:'<strong>190 mm</strong> fixed rod length<small>2 end connectors · part 91108</small>';$('#path-radius').textContent=`Smallest sampled bend radius: ${Number.isFinite(result.minimumRadius)?result.minimumRadius.toFixed(0)+' mm':'straight'}. Geometric estimate, not a verified limit.`;}catch(e){$('#path-error').textContent=e.message;$('#path-stats').textContent='Adjust the highlighted path.';}
 // Dashed guide represents the drawn reference, not an extra K’NEX part.
 const line=new T.Line(new T.BufferGeometry().setFromPoints(design.points.map(V)),new T.LineDashedMaterial({color:0x7a8eac,dashSize:7,gapSize:5,transparent:true,opacity:.7}));line.computeLineDistances();guides.add(line);
 design.points.forEach((p,i)=>{const m=new T.Mesh(new T.SphereGeometry(i===selected?7:5.5,16,12),new T.MeshBasicMaterial({color:i===selected?0xff50d3:0xf596df,depthTest:false}));m.position.fromArray(p);m.userData.index=i;m.renderOrder=10;handles.add(m);});
 $('#path-apply').disabled=!result;$('#path-track-controls').hidden=design.kind!=='track';$('.path-badge').textContent=design.kind==='track'?'Layout preview · supports needed':'Fixed-length shape · bend limits unverified';$('#path-units').textContent=design.kind==='track'?'Handle position · mm':'Reference handles · shape fits 190 mm';$('#path-source').innerHTML=design.kind==='track'?'<a href="https://shop.knexusergroup.org.uk/products/91430" target="_blank" rel="noreferrer">91430 green cross-ties</a> and purple split tubing from <a href="https://www.knexusergroup.org.uk/bk/51587.pdf" target="_blank" rel="noreferrer">Thunderbolt Strike 51587, pages 5, 34–39</a>. Each rail is cut from a 6.096 m stock length. Tie dimensions are estimated.':'<a href="https://shop.knexusergroup.org.uk/products/91108" target="_blank" rel="noreferrer">91108 green flexi rod, approx. 190 mm</a>, with 90901 gray end connectors. The reference shape is resized to preserve stock length.';
 dialog.querySelectorAll('[data-path-kind]').forEach(b=>b.setAttribute('aria-pressed',String(design.kind===b.dataset.pathKind)));nodes(); }
 function fit(){const box=new T.Box3().setFromPoints(design.points.map(V));if(result)box.union(new T.Box3().setFromObject(parts));const center=box.getCenter(new T.Vector3()),size=Math.max(220,box.getSize(new T.Vector3()).length()),direction=view==='top'?V([0,1,.0001]):view==='front'?V([0,0,1]):V([.8,.65,1]).normalize();controls.target.copy(center);camera.position.copy(center).addScaledVector(direction,size*1.2);camera.up.set(0,1,0);controls.enableRotate=view==='3d';controls.update();}
 function resize(){const r=$('#path-canvas').getBoundingClientRect();renderer.setSize(r.width,r.height);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();}const observer=new ResizeObserver(resize);observer.observe($('#path-canvas'));
 function locate(e){const r=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(pointer,camera);}
 renderer.domElement.addEventListener('pointerdown',e=>{if(e.button!==0)return;locate(e);const hit=ray.intersectObjects(handles.children)[0];if(!hit)return;e.stopImmediatePropagation();e.preventDefault();selected=hit.object.userData.index;const point=V(design.points[selected]),normal=e.shiftKey||view==='front'?camera.getWorldDirection(new T.Vector3()):V([0,1,0]),plane=new T.Plane().setFromNormalAndCoplanarPoint(normal,point),anchor=ray.ray.intersectPlane(plane,new T.Vector3());if(!anchor)return;drag={plane,anchor,point,height:e.shiftKey,before:design.points.map(p=>[...p])};controls.enabled=false;renderer.domElement.setPointerCapture(e.pointerId);redraw();},true);
 renderer.domElement.addEventListener('pointermove',e=>{if(!drag)return;locate(e);const next=ray.ray.intersectPlane(drag.plane,new T.Vector3());if(!next)return;const delta=next.sub(drag.anchor),p=drag.point.clone();if(drag.height)p.y+=delta.y;else p.add(delta);design.points[selected]=p.toArray().map(v=>Math.max(-2500,Math.min(2500,Math.round(v/2)*2)));redraw();});
 function release(){drag=null;controls.enabled=true;}
 renderer.domElement.addEventListener('pointerup',release);renderer.domElement.addEventListener('pointercancel',()=>{if(drag){design.points=drag.before;redraw();}release();});
 dialog.querySelectorAll('[data-path-view]').forEach(b=>b.onclick=()=>{view=b.dataset.pathView;dialog.querySelectorAll('[data-path-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));fit();});
 dialog.querySelectorAll('[data-path-kind]').forEach(b=>b.onclick=()=>{design.kind=b.dataset.pathKind;redraw();fit();});dialog.querySelectorAll('[data-path-preset]').forEach(b=>b.onclick=()=>{design.points=PATH_PRESETS[b.dataset.pathPreset].map(p=>[...p]);selected=1;redraw();fit();});
 $('#path-fit').onclick=fit;$('#path-hints').onclick=()=>{hints=!hints;$('#path-help').hidden=!hints;$('#path-hints').setAttribute('aria-pressed',String(hints));};$('#path-add').onclick=()=>{if(design.points.length>=24)return;const p=V(design.points.at(-1)).multiplyScalar(2).sub(V(design.points.at(-2)));design.points.push(p.toArray().map(v=>Math.max(-2500,Math.min(2500,v))));selected=design.points.length-1;redraw();fit();};$('#path-remove').onclick=()=>{if(design.points.length<=2)return;design.points.splice(selected,1);selected=Math.min(selected,design.points.length-1);redraw();};
 ['x','y','z'].forEach((a,i)=>$('#path-'+a).onchange=()=>{design.points[selected][i]=Number($('#path-'+a).value);redraw();});$('#path-spacing').onchange=()=>{design.spacing=Number($('#path-spacing').value);redraw();};$('#path-bank').onchange=()=>{design.bank=Number($('#path-bank').value);redraw();};
 $('#path-import').onclick=()=>$('#path-file').click();$('#path-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>64000)throw Error('Path file is too large (maximum 64 KB).');const value=parseDesign(await file.text());if(closed)return;design=value;selected=0;$('#path-spacing').value=design.spacing;$('#path-bank').value=design.bank;redraw();fit();}catch(err){if(!closed)$('#path-error').textContent=err.message;}e.target.value='';};
 $('#path-export').onclick=()=>{try{const blob=new Blob([exportDesign(design)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='knex-path.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){$('#path-error').textContent=e.message;}};
 $('#path-apply').onclick=()=>{if(!result)return;try{const next=parseModel(exportModel(model)),generated=parseModel(exportModel(result.model));if(next.parts.length+generated.parts.length>2500)throw Error('Maximum 2500 parts per model.');const dx=next.parts.length?Math.max(...next.parts.map(p=>p.pos[0]))+500:0;generated.parts.forEach(p=>p.pos[0]+=dx);next.parts.push(...generated.parts);next.links.push(...generated.links);makeGroup(next,generated.parts.map(p=>p.id),design.kind==='track'?'Coaster track':'Flexi');commit(next);dialog.close();}catch(e){$('#path-error').textContent=e.message;}};
 function dispose(){if(closed)return;closed=true;cancelAnimationFrame(frame);observer.disconnect();controls.dispose();clear();grid.geometry.dispose();grid.material.dispose();renderer.dispose();dialog.classList.remove('path-dialog');dialog.removeEventListener('close',dispose);}
 dialog.addEventListener('close',dispose);function animate(){if(closed)return;controls.update();renderer.render(scene,camera);frame=requestAnimationFrame(animate);}resize();redraw();fit();animate();return dispose;
}
